import { createHmac } from 'crypto'

export const IMPERSONATION_COOKIE = 'convertscan_impersonation'

export interface ImpersonationPayload {
  admin_id: string
  target_id: string
  session_id: string
  expires_ts: number
}

function getSecret(): string {
  const secret = process.env.IMPERSONATION_COOKIE_SECRET
  if (!secret) {
    throw new Error('CONFIG_ERROR: IMPERSONATION_COOKIE_SECRET is not set')
  }
  return secret
}

function buildPayloadString(p: ImpersonationPayload): string {
  return `${p.admin_id}.${p.target_id}.${p.session_id}.${p.expires_ts}`
}

function computeHmac(payload: string, secret: string): string {
  return createHmac('sha256', secret).update(payload).digest('base64url')
}

/**
 * Signs an impersonation cookie value.
 * Format: base64url(payload).hmac
 */
export function signImpersonationCookie(p: ImpersonationPayload): string {
  const secret = getSecret()
  const payload = buildPayloadString(p)
  const payloadB64 = Buffer.from(payload).toString('base64url')
  const hmac = computeHmac(payload, secret)
  return `${payloadB64}.${hmac}`
}

/**
 * Verifies a signed cookie value and returns the payload, or null if invalid/expired.
 */
export function verifyImpersonationCookie(raw: string): ImpersonationPayload | null {
  try {
    const secret = getSecret()
    const dotIdx = raw.lastIndexOf('.')
    if (dotIdx === -1) return null

    const payloadB64 = raw.slice(0, dotIdx)
    const hmac = raw.slice(dotIdx + 1)

    const payload = Buffer.from(payloadB64, 'base64url').toString('utf-8')
    const expectedHmac = computeHmac(payload, secret)

    // Constant-time comparison to prevent timing attacks
    if (hmac.length !== expectedHmac.length) return null
    let diff = 0
    for (let i = 0; i < hmac.length; i++) {
      diff |= hmac.charCodeAt(i) ^ expectedHmac.charCodeAt(i)
    }
    if (diff !== 0) return null

    const parts = payload.split('.')
    if (parts.length !== 4) return null

    const [admin_id, target_id, session_id, expires_ts_str] = parts
    const expires_ts = parseInt(expires_ts_str, 10)
    if (isNaN(expires_ts)) return null

    // Check expiry
    if (expires_ts < Date.now()) return null

    if (!admin_id || !target_id || !session_id) return null

    return { admin_id, target_id, session_id, expires_ts }
  } catch {
    return null
  }
}

'use server'

import { getAuthenticatedUser } from '@/lib/supabase/server'

export class ActionError extends Error {
  constructor(
    public readonly code: string,
    message: string,
  ) {
    super(message)
    this.name = 'ActionError'
  }
}

export async function requireAdmin() {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    throw new ActionError('UNAUTHENTICATED', 'Sign in required')
  }
  if (!['admin', 'super_admin'].includes(auth.user.role)) {
    throw new ActionError('FORBIDDEN', 'Admin access required')
  }
  return auth
}

export async function requireSuperAdmin() {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    throw new ActionError('UNAUTHENTICATED', 'Sign in required')
  }
  if (auth.user.role !== 'super_admin') {
    throw new ActionError('FORBIDDEN', 'Super admin access required')
  }
  return auth
}

export type ActionResult<T = void> =
  | { ok: true; data: T }
  | { ok: false; error: string; code: string }

import { createServiceRoleClient } from '@/lib/supabase/server'
import type { AdminErrorLogInsert } from '@/types/database'

interface ServerErrorContext {
  source?: 'server' | 'edge' | 'cron'
  severity?: 'fatal' | 'error' | 'warning' | 'info'
  route?: string
  userId?: string | null
  metadata?: Record<string, unknown>
}

/**
 * Fire-and-forget server-side error logger.
 * Inserts into admin_error_log via service role (bypasses RLS).
 * Also forwards to Sentry if NEXT_PUBLIC_SENTRY_DSN is set.
 * Never throws — safe to call in catch blocks.
 */
export async function logServerError(
  err: unknown,
  ctx: ServerErrorContext = {},
): Promise<void> {
  try {
    let message: string
    let stack: string | null = null

    if (err instanceof Error) {
      message = err.message
      stack = err.stack ?? null
    } else {
      message = String(err)
    }

    const insert: AdminErrorLogInsert = {
      message: message.slice(0, 2000),
      source: ctx.source ?? 'server',
      severity: ctx.severity ?? 'error',
      stack: stack ? stack.slice(0, 20000) : null,
      route: ctx.route ?? null,
      user_id: ctx.userId ?? null,
      metadata: ctx.metadata ?? {},
    }

    const sr = createServiceRoleClient()
    await sr.from('admin_error_log').insert(insert)

    // Forward to Sentry if configured
    if (process.env.NEXT_PUBLIC_SENTRY_DSN && err instanceof Error) {
      const Sentry = await import('@sentry/nextjs')
      Sentry.captureException(err, { tags: { source: ctx.source ?? 'server', route: ctx.route ?? 'unknown' } })
    }
  } catch {
    // Swallow — error logging must never throw
  }
}

interface ClientErrorContext {
  route?: string
  metadata?: Record<string, unknown>
}

/**
 * Fire-and-forget client-side error logger.
 * POSTs to /api/admin/errors (no-await).
 * Also mirrors to Sentry if loaded.
 */
export function logClientError(
  err: unknown,
  ctx: ClientErrorContext = {},
): void {
  const message = err instanceof Error ? err.message : String(err)
  const stack = err instanceof Error ? (err.stack ?? null) : null

  // No-await POST — best effort
  fetch('/api/admin/errors', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      severity: 'error',
      message: message.slice(0, 2000),
      stack: stack ? stack.slice(0, 20000) : undefined,
      url: typeof window !== 'undefined' ? window.location.href : undefined,
      route: ctx.route ?? (typeof window !== 'undefined' ? window.location.pathname : undefined),
      source: 'client',
      metadata: ctx.metadata,
    }),
  }).catch(() => {
    // Swallow network errors
  })

  // Mirror to Sentry if available
  try {
    if (typeof window !== 'undefined' && (window as Window & { Sentry?: { captureException: (e: unknown) => void } }).Sentry && err instanceof Error) {
      (window as Window & { Sentry?: { captureException: (e: unknown) => void } }).Sentry?.captureException(err)
    }
  } catch {
    // Swallow
  }
}

'use server'

import { z } from 'zod'
import { headers, cookies } from 'next/headers'
import { createServiceRoleClient } from '@/lib/supabase/server'
import {
  signImpersonationCookie,
  verifyImpersonationCookie,
  IMPERSONATION_COOKIE,
} from '@/lib/admin/impersonation-cookie'
import { requireSuperAdmin, requireAdmin, ActionError, type ActionResult } from './_guard'
import { revalidatePath } from 'next/cache'

export const impersonateSchema = z.object({
  targetUserId: z.string().uuid(),
  reason: z.string().min(10).max(500),
})

export async function impersonateUser(
  input: z.infer<typeof impersonateSchema>,
): Promise<ActionResult<{ redirectTo: string }>> {
  try {
    const admin = await requireSuperAdmin()
    const parsed = impersonateSchema.safeParse(input)
    if (!parsed.success) {
      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
    }

    const { targetUserId, reason } = parsed.data

    if (targetUserId === admin.user.id) {
      return { ok: false, error: 'Cannot impersonate yourself', code: 'FORBIDDEN' }
    }

    const sr = createServiceRoleClient()

    // Check target exists and is not super_admin
    const { data: target, error: targetErr } = await sr
      .from('profiles')
      .select('id, role, email')
      .eq('id', targetUserId)
      .single()

    if (targetErr || !target) {
      return { ok: false, error: 'User not found', code: 'NOT_FOUND' }
    }

    if (target.role === 'super_admin') {
      return { ok: false, error: 'Cannot impersonate a super admin', code: 'FORBIDDEN' }
    }

    // Capture request metadata
    const headerStore = await headers()
    const ipAddress = headerStore.get('x-forwarded-for')?.split(',')[0]?.trim() ?? null
    const userAgent = headerStore.get('user-agent') ?? null

    const expiresAt = new Date(Date.now() + 30 * 60 * 1000).toISOString()

    // Create impersonation session
    const { data: session, error: sessionErr } = await sr
      .from('admin_impersonation_sessions')
      .insert({
        admin_user_id: admin.user.id,
        target_user_id: targetUserId,
        expires_at: expiresAt,
        reason,
        ip_address: ipAddress,
        user_agent: userAgent,
      })
      .select('id')
      .single()

    if (sessionErr || !session) {
      return { ok: false, error: 'Failed to create impersonation session', code: 'DB_ERROR' }
    }

    // Write audit log
    await sr.from('audit_logs').insert({
      admin_id: admin.user.id,
      action: 'impersonate.start',
      target_type: 'user',
      target_id: targetUserId,
      metadata: {
        session_id: session.id,
        reason,
        expires_at: expiresAt,
        target_email: target.email,
      },
    })

    // Sign and set cookie
    const cookieValue = signImpersonationCookie({
      admin_id: admin.user.id,
      target_id: targetUserId,
      session_id: session.id,
      expires_ts: Date.now() + 30 * 60 * 1000,
    })

    const cookieStore = await cookies()
    cookieStore.set(IMPERSONATION_COOKIE, cookieValue, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 1800,
    })

    revalidatePath('/dashboard')
    return { ok: true, data: { redirectTo: '/dashboard' } }
  } catch (err) {
    if (err instanceof ActionError) {
      return { ok: false, error: err.message, code: err.code }
    }
    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
  }
}

export async function endImpersonation(): Promise<ActionResult<{ redirectTo: string }>> {
  try {
    await requireAdmin()

    const cookieStore = await cookies()
    const rawCookie = cookieStore.get(IMPERSONATION_COOKIE)?.value

    if (!rawCookie) {
      return { ok: false, error: 'No active impersonation session', code: 'NOT_FOUND' }
    }

    const payload = verifyImpersonationCookie(rawCookie)
    if (!payload) {
      cookieStore.delete(IMPERSONATION_COOKIE)
      return { ok: false, error: 'Invalid or expired impersonation cookie', code: 'INVALID_COOKIE' }
    }

    const sr = createServiceRoleClient()

    // End the session
    await sr
      .from('admin_impersonation_sessions')
      .update({ ended_at: new Date().toISOString() })
      .eq('id', payload.session_id)
      .is('ended_at', null)

    // Write audit log
    await sr.from('audit_logs').insert({
      admin_id: payload.admin_id,
      action: 'impersonate.end',
      target_type: 'user',
      target_id: payload.target_id,
      metadata: { session_id: payload.session_id },
    })

    // Clear cookie
    cookieStore.delete(IMPERSONATION_COOKIE)

    revalidatePath('/admin/users')
    return { ok: true, data: { redirectTo: `/admin/users/${payload.target_id}` } }
  } catch (err) {
    if (err instanceof ActionError) {
      return { ok: false, error: err.message, code: err.code }
    }
    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
  }
}

'use server'

import { z } from 'zod'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { requireSuperAdmin, ActionError, type ActionResult } from './_guard'
import { revalidatePath } from 'next/cache'

export const grantCreditsSchema = z.object({
  userId: z.string().uuid(),
  amount: z.number().int().min(1).max(1000),
  reason: z.string().min(5).max(500),
})

export async function grantScanCredits(
  input: z.infer<typeof grantCreditsSchema>,
): Promise<ActionResult<{ newLimit: number }>> {
  try {
    const admin = await requireSuperAdmin()

    const parsed = grantCreditsSchema.safeParse(input)
    if (!parsed.success) {
      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
    }

    const { userId, amount, reason } = parsed.data
    const sr = createServiceRoleClient()

    const { data, error } = await sr
      .rpc('increment_scan_limit', { user_uuid: userId, increment_by: amount })

    // Fallback: direct update if RPC not available
    if (error) {
      const { data: updated, error: updateErr } = await sr
        .from('profiles')
        .select('scan_limit')
        .eq('id', userId)
        .single()

      if (updateErr || !updated) {
        return { ok: false, error: 'User not found', code: 'NOT_FOUND' }
      }

      const newLimit = updated.scan_limit + amount
      const { error: setErr } = await sr
        .from('profiles')
        .update({ scan_limit: newLimit })
        .eq('id', userId)

      if (setErr) {
        return { ok: false, error: 'Failed to update scan limit', code: 'DB_ERROR' }
      }

      await sr.from('audit_logs').insert({
        admin_id: admin.user.id,
        action: 'credits.grant',
        target_type: 'user',
        target_id: userId,
        metadata: { amount, reason, new_limit: newLimit },
      })

      revalidatePath(`/admin/users/${userId}`)
      return { ok: true, data: { newLimit } }
    }

    const newLimit = typeof data === 'number' ? data : 0

    await sr.from('audit_logs').insert({
      admin_id: admin.user.id,
      action: 'credits.grant',
      target_type: 'user',
      target_id: userId,
      metadata: { amount, reason, new_limit: newLimit },
    })

    revalidatePath(`/admin/users/${userId}`)
    return { ok: true, data: { newLimit } }
  } catch (err) {
    if (err instanceof ActionError) {
      return { ok: false, error: err.message, code: err.code }
    }
    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
  }
}

'use server'

import { z } from 'zod'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { requireAdmin, ActionError, type ActionResult } from './_guard'
import { revalidatePath } from 'next/cache'

export const requeueStuckSchema = z.object({
  olderThanMinutes: z.number().int().min(5).max(1440).default(15),
})

export async function requeueStuckScans(
  input: z.infer<typeof requeueStuckSchema> = { olderThanMinutes: 15 },
): Promise<ActionResult<{ count: number; scanIds: string[] }>> {
  try {
    const admin = await requireAdmin()

    const parsed = requeueStuckSchema.safeParse(input)
    if (!parsed.success) {
      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
    }

    const { olderThanMinutes } = parsed.data
    const cutoff = new Date(Date.now() - olderThanMinutes * 60 * 1000).toISOString()

    const sr = createServiceRoleClient()

    // Find stuck scans (limit 50)
    const { data: stuckScans, error: fetchErr } = await sr
      .from('scans')
      .select('id')
      .eq('status', 'analyzing')
      .lt('created_at', cutoff)
      .limit(50)

    if (fetchErr) {
      return { ok: false, error: 'Failed to fetch stuck scans', code: 'DB_ERROR' }
    }

    if (!stuckScans || stuckScans.length === 0) {
      return { ok: true, data: { count: 0, scanIds: [] } }
    }

    const scanIds = stuckScans.map((s) => s.id)

    const { error: updateErr } = await sr
      .from('scans')
      .update({ status: 'pending', error_message: null })
      .in('id', scanIds)

    if (updateErr) {
      return { ok: false, error: 'Failed to requeue scans', code: 'DB_ERROR' }
    }

    await sr.from('audit_logs').insert({
      admin_id: admin.user.id,
      action: 'queue.requeue_bulk',
      target_type: null,
      target_id: null,
      metadata: { count: scanIds.length, scan_ids: scanIds, threshold_minutes: olderThanMinutes },
    })

    revalidatePath('/admin/system')
    return { ok: true, data: { count: scanIds.length, scanIds } }
  } catch (err) {
    if (err instanceof ActionError) {
      return { ok: false, error: err.message, code: err.code }
    }
    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
  }
}

export const requeueSingleSchema = z.object({
  scanId: z.string().uuid(),
})

export async function requeueSingleScan(
  input: z.infer<typeof requeueSingleSchema>,
): Promise<ActionResult<{ scanId: string }>> {
  try {
    const admin = await requireAdmin()

    const parsed = requeueSingleSchema.safeParse(input)
    if (!parsed.success) {
      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
    }

    const { scanId } = parsed.data
    const sr = createServiceRoleClient()

    const { error } = await sr
      .from('scans')
      .update({ status: 'pending', error_message: null })
      .eq('id', scanId)
      .in('status', ['failed', 'analyzing'])

    if (error) {
      return { ok: false, error: 'Failed to requeue scan', code: 'DB_ERROR' }
    }

    await sr.from('audit_logs').insert({
      admin_id: admin.user.id,
      action: 'queue.requeue_single',
      target_type: 'scan',
      target_id: scanId,
      metadata: {},
    })

    revalidatePath('/admin/system')
    return { ok: true, data: { scanId } }
  } catch (err) {
    if (err instanceof ActionError) {
      return { ok: false, error: err.message, code: err.code }
    }
    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
  }
}

'use server'

import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { requireSuperAdmin, ActionError, type ActionResult } from './_guard'
import { revalidatePath } from 'next/cache'

export const resolveErrorSchema = z.object({
  errorId: z.string().uuid(),
  note: z.string().min(3).max(1000),
})

export async function resolveErrorLog(
  input: z.infer<typeof resolveErrorSchema>,
): Promise<ActionResult<void>> {
  try {
    const admin = await requireSuperAdmin()

    const parsed = resolveErrorSchema.safeParse(input)
    if (!parsed.success) {
      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
    }

    const { errorId, note } = parsed.data

    // Use session client — RLS policy error_log_super_admin_update enforces role
    const supabase = await createClient()

    const { error } = await supabase
      .from('admin_error_log')
      .update({
        resolved: true,
        resolved_at: new Date().toISOString(),
        resolved_by: admin.user.id,
        resolution_note: note,
      })
      .eq('id', errorId)
      .eq('resolved', false)

    if (error) {
      return { ok: false, error: 'Failed to resolve error log', code: 'DB_ERROR' }
    }

    // Write audit log via service role
    const sr = createServiceRoleClient()
    await sr.from('audit_logs').insert({
      admin_id: admin.user.id,
      action: 'errorlog.resolve',
      target_type: 'error_log',
      target_id: errorId,
      metadata: { note },
    })

    revalidatePath('/admin/errors')
    return { ok: true, data: undefined }
  } catch (err) {
    if (err instanceof ActionError) {
      return { ok: false, error: err.message, code: err.code }
    }
    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
  }
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createServiceRoleClient, createClient } from '@/lib/supabase/server'
import type { AdminErrorLogInsert } from '@/types/database'

// ── In-memory rate limiter (30 req / 5 min per IP) ────────────
// Sprint 2 upgrade: Redis-backed bucket via Railway KV / Upstash
interface RateLimitEntry {
  count: number
  resetAt: number
}

const rateLimitMap = new Map<string, RateLimitEntry>()
const RATE_LIMIT_MAX = 30
const RATE_LIMIT_WINDOW_MS = 5 * 60 * 1000

function checkRateLimit(ip: string): boolean {
  const now = Date.now()
  const entry = rateLimitMap.get(ip)

  if (!entry || now > entry.resetAt) {
    rateLimitMap.set(ip, { count: 1, resetAt: now + RATE_LIMIT_WINDOW_MS })
    return true
  }

  if (entry.count >= RATE_LIMIT_MAX) {
    return false
  }

  entry.count++
  return true
}

const bodySchema = z.object({
  severity: z.enum(['fatal', 'error', 'warning', 'info']).optional().default('error'),
  message: z.string().min(1).max(2000),
  stack: z.string().max(20000).optional(),
  url: z.string().max(2048).optional(),
  route: z.string().max(500).optional(),
  source: z.enum(['server', 'client', 'edge', 'cron']).optional().default('client'),
  metadata: z.record(z.unknown()).optional(),
})

export async function POST(request: Request) {
  // Extract IP for rate limiting
  const forwarded = request.headers.get('x-forwarded-for')
  const ip = forwarded ? forwarded.split(',')[0]?.trim() ?? 'unknown' : 'unknown'

  if (!checkRateLimit(ip)) {
    return new NextResponse(null, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return new NextResponse(null, { status: 400 })
  }

  const parsed = bodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.issues[0]?.message },
      { status: 400 },
    )
  }

  const { severity, message, stack, url, route, source, metadata } = parsed.data

  // Attempt to extract user_id from session (optional — errors may be pre-auth)
  let userId: string | null = null
  try {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    userId = user?.id ?? null
  } catch {
    // Session unavailable — ok
  }

  const insert: AdminErrorLogInsert = {
    message,
    source,
    severity,
    stack: stack ?? null,
    url: url ?? null,
    route: route ?? null,
    user_id: userId,
    metadata: (metadata as Record<string, unknown>) ?? {},
  }

  try {
    const sr = createServiceRoleClient()
    await sr.from('admin_error_log').insert(insert)
  } catch {
    // Swallow DB errors — don't surface to client
  }

  return new NextResponse(null, { status: 204 })
}

import { NextResponse } from 'next/server'
import { endImpersonation } from '@/app/actions/admin/impersonation'

export async function POST() {
  const result = await endImpersonation()

  if (!result.ok) {
    return NextResponse.json({ error: result.error, code: result.code }, { status: 400 })
  }

  return NextResponse.json({ redirectTo: result.data.redirectTo })
}

import { NextResponse, type NextRequest } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'

export async function GET(request: NextRequest) {
  const impersonatingUserId = request.headers.get('x-impersonating-user')

  if (!impersonatingUserId) {
    return NextResponse.json({ active: false, targetEmail: null, expiresAt: null })
  }

  // Look up target email and session expiry
  try {
    const sr = createServiceRoleClient()
    const { data: profile } = await sr
      .from('profiles')
      .select('email')
      .eq('id', impersonatingUserId)
      .single()

    // Get latest active session
    const { data: session } = await sr
      .from('admin_impersonation_sessions')
      .select('expires_at')
      .eq('target_user_id', impersonatingUserId)
      .is('ended_at', null)
      .order('started_at', { ascending: false })
      .limit(1)
      .single()

    return NextResponse.json({
      active: true,
      targetEmail: profile?.email ?? null,
      expiresAt: session?.expires_at ?? null,
    })
  } catch {
    return NextResponse.json({ active: true, targetEmail: null, expiresAt: null })
  }
}

