'use client'

import { useEffect, useState, useCallback } from 'react'
import { ShieldAlert, X, Clock } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { useRouter } from 'next/navigation'

interface ImpersonationState {
  active: boolean
  targetEmail: string | null
  expiresAt: string | null
}

function useCountdown(expiresAt: string | null): string {
  const [remaining, setRemaining] = useState('')

  useEffect(() => {
    if (!expiresAt) return

    function update() {
      const diff = new Date(expiresAt!).getTime() - Date.now()
      if (diff <= 0) {
        setRemaining('Expired')
        return
      }
      const mins = Math.floor(diff / 60000)
      const secs = Math.floor((diff % 60000) / 1000)
      setRemaining(`${mins}m ${secs.toString().padStart(2, '0')}s`)
    }

    update()
    const id = setInterval(update, 1000)
    return () => clearInterval(id)
  }, [expiresAt])

  return remaining
}

export function ImpersonationBanner() {
  const [state, setState] = useState<ImpersonationState>({ active: false, targetEmail: null, expiresAt: null })
  const [isExiting, setIsExiting] = useState(false)
  const router = useRouter()
  const countdown = useCountdown(state.expiresAt)

  const fetchState = useCallback(async () => {
    try {
      const res = await fetch('/api/admin/impersonate/state', { cache: 'no-store' })
      if (!res.ok) return
      const data = await res.json() as ImpersonationState
      setState(data)
    } catch {
      // Silently ignore
    }
  }, [])

  useEffect(() => {
    fetchState()
    const id = setInterval(fetchState, 30_000)
    return () => clearInterval(id)
  }, [fetchState])

  const handleExit = async () => {
    setIsExiting(true)
    try {
      const res = await fetch('/api/admin/impersonate/end', { method: 'POST' })
      if (!res.ok) return
      const data = await res.json() as { redirectTo?: string }
      setState({ active: false, targetEmail: null, expiresAt: null })
      router.push(data.redirectTo ?? '/admin/users')
      router.refresh()
    } catch {
      setIsExiting(false)
    }
  }

  if (!state.active) return null

  return (
    <div
      role="alert"
      aria-live="polite"
      className="flex items-center justify-between gap-3 bg-red-600 px-4 py-2 text-white text-sm font-medium"
    >
      <div className="flex items-center gap-2">
        <ShieldAlert className="h-4 w-4 shrink-0" />
        <span>
          Acting as{' '}
          <strong className="font-semibold">{state.targetEmail ?? 'unknown user'}</strong>
          {' — actions are being logged'}
        </span>
      </div>
      <div className="flex items-center gap-3 shrink-0">
        {countdown && (
          <span className="flex items-center gap-1 text-red-100 text-xs">
            <Clock className="h-3.5 w-3.5" />
            {countdown}
          </span>
        )}
        <Button
          size="sm"
          variant="outline"
          onClick={handleExit}
          disabled={isExiting}
          className="h-7 border-red-300 bg-transparent text-white hover:bg-red-700 hover:border-red-200 hover:text-white text-xs font-medium"
        >
          <X className="h-3 w-3 mr-1" />
          Exit
        </Button>
      </div>
    </div>
  )
}

