import { Component, type ErrorInfo, type ReactNode } from 'react'
import { AlertTriangle, RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { logClientError } from '@/lib/errors/log-client'

interface Props {
  children: ReactNode
  fallback?: ReactNode
}

interface State {
  hasError: boolean
  errorMessage: string | null
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, errorMessage: null }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, errorMessage: error.message }
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    logClientError(error, {
      route: typeof window !== 'undefined' ? window.location.pathname : undefined,
      metadata: { componentStack: info.componentStack ?? undefined },
    })
  }

  handleReset = () => {
    this.setState({ hasError: false, errorMessage: null })
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) return this.props.fallback

      return (
        <div className="flex flex-col items-center justify-center gap-3 py-12 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10">
            <AlertTriangle className="h-6 w-6 text-destructive" />
          </div>
          <div className="space-y-1">
            <p className="text-sm font-medium text-foreground">Something went wrong</p>
            {this.state.errorMessage && (
              <p className="text-xs text-muted-foreground font-mono max-w-xs truncate">
                {this.state.errorMessage}
              </p>
            )}
          </div>
          <Button size="sm" variant="outline" onClick={this.handleReset}>
            <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
            Try again
          </Button>
        </div>
      )
    }

    return this.props.children
  }
}

'use client'

import { useEffect } from 'react'
import { logClientError } from '@/lib/errors/log-client'

/**
 * Registers global window.onerror and unhandledrejection listeners.
 * Mount once in the app layout as a leaf component.
 */
export function ClientErrorListener() {
  useEffect(() => {
    function handleError(event: ErrorEvent) {
      logClientError(event.error ?? new Error(event.message), {
        route: window.location.pathname,
        metadata: {
          filename: event.filename,
          lineno: event.lineno,
          colno: event.colno,
        },
      })
    }

    function handleUnhandledRejection(event: PromiseRejectionEvent) {
      const err = event.reason instanceof Error
        ? event.reason
        : new Error(String(event.reason))
      logClientError(err, {
        route: window.location.pathname,
        metadata: { type: 'unhandledrejection' },
      })
    }

    window.addEventListener('error', handleError)
    window.addEventListener('unhandledrejection', handleUnhandledRejection)

    return () => {
      window.removeEventListener('error', handleError)
      window.removeEventListener('unhandledrejection', handleUnhandledRejection)
    }
  }, [])

  return null
}

