const KIND_CONFIG: Record<string, { icon: React.ElementType; label: string; color: string }> = {
  scan: { icon: ScanLine, label: 'Scan', color: 'text-blue-500' },
  audit: { icon: Shield, label: 'Admin Action', color: 'text-amber-500' },
  support: { icon: MessageSquare, label: 'Support', color: 'text-purple-500' },
  impersonation: { icon: UserCog, label: 'Impersonation', color: 'text-red-500' },
}

function groupByDay(items: UserActivityRow[]): Array<{ label: string; items: UserActivityRow[] }> {
  const groups: Map<string, UserActivityRow[]> = new Map()

  for (const item of items) {
    const date = new Date(item.at)
    let key: string
    if (isToday(date)) key = 'Today'
    else if (isYesterday(date)) key = 'Yesterday'
    else key = format(date, 'MMMM d, yyyy')

    const existing = groups.get(key)
    if (existing) existing.push(item)
    else groups.set(key, [item])
  }

  return Array.from(groups.entries()).map(([label, items]) => ({ label, items }))
}

function TimelineItem({ item }: { item: UserActivityRow }) {
  const config = KIND_CONFIG[item.kind] ?? { icon: Shield, label: item.kind, color: 'text-muted-foreground' }
  const Icon = config.icon

  return (
    <div className="flex gap-3">
      <div className="flex flex-col items-center">
        <div className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted/50 ${config.color}`}>
          <Icon className="h-3.5 w-3.5" />
        </div>
        <div className="mt-1 w-px flex-1 bg-border/50" />
      </div>
      <div className="pb-4 pt-0.5 min-w-0 flex-1">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0 flex-1">
            <Badge className="mb-1 text-2xs border-0 bg-muted/50 text-foreground/80 capitalize">
              {config.label}
            </Badge>
            <p className="text-sm text-foreground truncate">
              {item.summary ?? '—'}
            </p>
            {item.metadata && Object.keys(item.metadata).length > 0 && (
              <p className="text-xs text-muted-foreground mt-0.5 font-mono truncate">
                {Object.entries(item.metadata)
                  .slice(0, 2)
                  .map(([k, v]) => `${k}: ${String(v)}`)
                  .join(' · ')}
              </p>
            )}
          </div>
          <time className="shrink-0 text-2xs text-muted-foreground tabular-nums">
            {format(new Date(item.at), 'HH:mm')}
          </time>
        </div>
      </div>
    </div>
  )
}

