import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { requeueStuckScans, requeueSingleScan } from '@/app/actions/admin/queue'
import type { ScanRow } from '@/types/database'

const STUCK_THRESHOLD_MINUTES = 15
const QUERY_KEY = ['admin', 'queue']

interface QueueStats {
  pendingCount: number
  analyzingCount: number
  failedCount24h: number
  stuckCount: number
}

export function useAdminQueueStats() {
  return useQuery<QueueStats>({
    queryKey: [...QUERY_KEY, 'stats'],
    queryFn: async () => {
      const supabase = createClient()
      const cutoff = new Date(Date.now() - STUCK_THRESHOLD_MINUTES * 60 * 1000).toISOString()
      const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

      const [pending, analyzing, failed24h, stuck] = await Promise.all([
        supabase.from('scans').select('id', { count: 'exact', head: true }).eq('status', 'pending'),
        supabase.from('scans').select('id', { count: 'exact', head: true }).eq('status', 'analyzing'),
        supabase.from('scans').select('id', { count: 'exact', head: true }).eq('status', 'failed').gte('created_at', since24h),
        supabase.from('scans').select('id', { count: 'exact', head: true }).eq('status', 'analyzing').lt('created_at', cutoff),
      ])

      return {
        pendingCount: pending.count ?? 0,
        analyzingCount: analyzing.count ?? 0,
        failedCount24h: failed24h.count ?? 0,
        stuckCount: stuck.count ?? 0,
      }
    },
    refetchInterval: 10_000,
    staleTime: 5_000,
  })
}

export function useStuckScans() {
  return useQuery<ScanRow[]>({
    queryKey: [...QUERY_KEY, 'stuck-scans'],
    queryFn: async () => {
      const supabase = createClient()
      const cutoff = new Date(Date.now() - STUCK_THRESHOLD_MINUTES * 60 * 1000).toISOString()
      const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

      const { data, error } = await supabase
        .from('scans')
        .select('*')
        .or(`and(status.eq.analyzing,created_at.lt.${cutoff}),and(status.eq.failed,created_at.gte.${since24h})`)
        .order('created_at', { ascending: false })
        .limit(50)

      if (error) throw error
      return data ?? []
    },
    refetchInterval: 10_000,
    staleTime: 5_000,
  })
}

export function useRequeueStuck() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (olderThanMinutes: number = STUCK_THRESHOLD_MINUTES) =>
      requeueStuckScans({ olderThanMinutes }),
    onSuccess: (result) => {
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success(`${result.data.count} scan${result.data.count === 1 ? '' : 's'} requeued`)
      void qc.invalidateQueries({ queryKey: QUERY_KEY })
    },
    onError: () => toast.error('Failed to requeue scans'),
  })
}

export function useRequeueSingle() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (input: { scanId: string }) => requeueSingleScan(input),
    onSuccess: (result) => {
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Scan requeued')
      void qc.invalidateQueries({ queryKey: QUERY_KEY })
    },
    onError: () => toast.error('Failed to requeue scan'),
  })
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { resolveErrorLog } from '@/app/actions/admin/errors'
import type { AdminErrorLogRow } from '@/types/database'

const QUERY_KEY = ['admin', 'error-log']
const PAGE_SIZE = 25

export interface ErrorFilters {
  severity?: ('fatal' | 'error' | 'warning' | 'info')[]
  source?: ('server' | 'client' | 'edge' | 'cron')[]
  resolved?: boolean
  search?: string
}

export interface ErrorStats {
  unresolved: number
  count24h: number
  fatal7d: number
}

export function useAdminErrors(filters: ErrorFilters = {}, cursor?: string) {
  return useQuery<{ items: AdminErrorLogRow[]; nextCursor: string | null }>({
    queryKey: [...QUERY_KEY, 'list', filters, cursor],
    queryFn: async () => {
      const supabase = createClient()

      let q = supabase
        .from('admin_error_log')
        .select('*')
        .order('occurred_at', { ascending: false })
        .limit(PAGE_SIZE)

      if (cursor) q = q.lt('occurred_at', cursor)
      if (filters.severity?.length) q = q.in('severity', filters.severity)
      if (filters.source?.length) q = q.in('source', filters.source)
      if (filters.resolved !== undefined) q = q.eq('resolved', filters.resolved)
      if (filters.search) q = q.ilike('message', `%${filters.search}%`)

      const { data, error } = await q
      if (error) throw error

      const items = (data as AdminErrorLogRow[]) ?? []
      const nextCursor = items.length === PAGE_SIZE
        ? items[items.length - 1]!.occurred_at
        : null

      return { items, nextCursor }
    },
    staleTime: 30_000,
  })
}

export function useAdminErrorStats() {
  return useQuery<ErrorStats>({
    queryKey: [...QUERY_KEY, 'stats'],
    queryFn: async () => {
      const supabase = createClient()
      const since24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
      const since7d = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()

      const [unresolved, count24h, fatal7d] = await Promise.all([
        supabase.from('admin_error_log').select('id', { count: 'exact', head: true }).eq('resolved', false),
        supabase.from('admin_error_log').select('id', { count: 'exact', head: true }).gte('occurred_at', since24h),
        supabase.from('admin_error_log').select('id', { count: 'exact', head: true }).eq('severity', 'fatal').gte('occurred_at', since7d),
      ])

      return {
        unresolved: unresolved.count ?? 0,
        count24h: count24h.count ?? 0,
        fatal7d: fatal7d.count ?? 0,
      }
    },
    staleTime: 60_000,
    refetchInterval: 60_000,
  })
}

export function useResolveError() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (input: { errorId: string; note: string }) => resolveErrorLog(input),
    onSuccess: (result) => {
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      toast.success('Error marked as resolved')
      void qc.invalidateQueries({ queryKey: QUERY_KEY })
    },
    onError: () => toast.error('Failed to resolve error'),
  })
}

