'use client'

import { useState } from 'react'
import {
  AlertTriangle,
  AlertCircle,
  CheckCircle2,
  Activity,
  Search,
  ChevronRight,
  X,
  Loader2,
} from 'lucide-react'
import { formatDistanceToNow, format } from 'date-fns'
import { PageHeader } from '@/components/shared/PageHeader'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Toggle } from '@/components/ui/toggle'
import {
  useAdminErrors,
  useAdminErrorStats,
  useResolveError,
  type ErrorFilters,
} from '@/hooks/admin/use-admin-errors'
import { useAuth } from '@/contexts/AuthContext'
import type { AdminErrorLogRow } from '@/types/database'

const SEVERITY_CONFIG = {
  fatal: { label: 'Fatal', color: 'bg-red-100 text-red-700 border-0' },
  error: { label: 'Error', color: 'bg-[--color-danger-subtle] text-[--color-danger-fg] border-0' },
  warning: { label: 'Warning', color: 'bg-[--color-warning-subtle] text-[--color-warning-fg] border-0' },
  info: { label: 'Info', color: 'bg-[--color-info-subtle] text-[--color-info-fg] border-0' },
} as const

const SOURCE_CONFIG = {
  server: 'bg-purple-50 text-purple-700 border-0',
  client: 'bg-blue-50 text-blue-700 border-0',
  edge: 'bg-amber-50 text-amber-700 border-0',
  cron: 'bg-green-50 text-green-700 border-0',
} as const

type SeverityKey = keyof typeof SEVERITY_CONFIG
type SourceKey = keyof typeof SOURCE_CONFIG

function ErrorDetailSheet({
  error,
  open,
  onClose,
  isSuperAdmin,
}: {
  error: AdminErrorLogRow | null
  open: boolean
  onClose: () => void
  isSuperAdmin: boolean
}) {
  const [note, setNote] = useState('')
  const resolve = useResolveError()

  if (!error) return null

  const sevConfig = SEVERITY_CONFIG[error.severity as SeverityKey]
  const srcClass = SOURCE_CONFIG[error.source as SourceKey] ?? 'bg-muted/50 text-foreground/80 border-0'

  const handleResolve = async () => {
    if (!note.trim() || note.trim().length < 3) return
    await resolve.mutateAsync({ errorId: error.id, note: note.trim() })
    setNote('')
    onClose()
  }

  return (
    <Sheet open={open} onOpenChange={(v) => { if (!v) onClose() }}>
      <SheetContent className="w-full sm:max-w-lg overflow-y-auto">
        <SheetHeader className="mb-4">
          <SheetTitle className="flex items-center gap-2 flex-wrap">
            <Badge className={sevConfig?.color ?? 'bg-muted/50 text-foreground/80 border-0'}>
              {sevConfig?.label ?? error.severity}
            </Badge>
            <Badge className={srcClass}>{error.source}</Badge>
            {error.resolved && (
              <Badge className="bg-[--color-success-subtle] text-[--color-success-fg] border-0">Resolved</Badge>
            )}
          </SheetTitle>
          <SheetDescription className="font-mono text-xs text-muted-foreground">
            {error.id}
          </SheetDescription>
        </SheetHeader>

        <div className="space-y-5">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Message</p>
            <p className="text-sm text-foreground break-words">{error.message}</p>
          </div>

          {error.route && (
            <div>
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Route</p>
              <code className="text-xs font-mono text-foreground bg-muted/40 px-2 py-1 rounded">{error.route}</code>
            </div>
          )}

          {error.url && (
            <div>
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">URL</p>
              <p className="text-xs font-mono text-foreground break-all">{error.url}</p>
            </div>
          )}

          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Occurred</p>
            <p className="text-sm text-foreground">
              {format(new Date(error.occurred_at), 'MMM d, yyyy HH:mm:ss')}
              {' '}
              <span className="text-muted-foreground">
                ({formatDistanceToNow(new Date(error.occurred_at), { addSuffix: true })})
              </span>
            </p>
          </div>

          {error.stack && (
            <div>
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Stack Trace</p>
              <pre className="text-xs font-mono bg-muted/40 rounded-lg p-3 overflow-x-auto whitespace-pre-wrap break-words max-h-64 overflow-y-auto">
                {error.stack}
              </pre>
            </div>
          )}

          {Object.keys(error.metadata ?? {}).length > 0 && (
            <div>
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">Metadata</p>
              <pre className="text-xs font-mono bg-muted/40 rounded-lg p-3 overflow-x-auto max-h-48 overflow-y-auto">
                {JSON.stringify(error.metadata, null, 2)}
              </pre>
            </div>
          )}

          {error.resolved && error.resolution_note && (
            <div className="rounded-lg bg-[--color-success-subtle] p-3">
              <p className="text-xs font-semibold uppercase tracking-wider text-[--color-success-fg] mb-1">Resolution Note</p>
              <p className="text-sm text-foreground">{error.resolution_note}</p>
              {error.resolved_at && (
                <p className="text-xs text-muted-foreground mt-1">
                  {format(new Date(error.resolved_at), 'MMM d, yyyy HH:mm')}
                </p>
              )}
            </div>
          )}

          {!error.resolved && isSuperAdmin && (
            <div className="border-t border-border pt-4 space-y-3">
              <p className="text-sm font-medium text-foreground">Resolve this error</p>
              <div className="space-y-2">
                <Label htmlFor="resolve-note" className="text-xs font-medium">
                  Resolution note <span className="text-destructive">*</span>
                </Label>
                <Textarea
                  id="resolve-note"
                  placeholder="Describe what was fixed or why this can be ignored (min 3 chars)"
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  rows={3}
                  maxLength={1000}
                  className="resize-none"
                />
              </div>
              <Button
                onClick={handleResolve}
                disabled={note.trim().length < 3 || resolve.isPending}
                className="w-full"
              >
                {resolve.isPending && <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />}
                Mark as Resolved
              </Button>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  )
}

export default function AdminErrorsPage() {
  const { profile } = useAuth()
  const isSuperAdmin = profile?.role === 'super_admin'

  const [filters, setFilters] = useState<ErrorFilters>({ resolved: false })
  const [search, setSearch] = useState('')
  const [cursor, setCursor] = useState<string | undefined>()
  const [selectedError, setSelectedError] = useState<AdminErrorLogRow | null>(null)
  const [sheetOpen, setSheetOpen] = useState(false)

  const activeFilters: ErrorFilters = {
    ...filters,
    search: search.length >= 2 ? search : undefined,
  }

  const { data, isLoading } = useAdminErrors(activeFilters, cursor)
  const { data: stats, isLoading: statsLoading } = useAdminErrorStats()

  const toggleSeverity = (sev: SeverityKey) => {
    setFilters((prev) => {
      const current = prev.severity ?? []
      return {
        ...prev,
        severity: current.includes(sev) ? current.filter((s) => s !== sev) : [...current, sev],
      }
    })
    setCursor(undefined)
  }

  const toggleSource = (src: SourceKey) => {
    setFilters((prev) => {
      const current = prev.source ?? []
      return {
        ...prev,
        source: current.includes(src) ? current.filter((s) => s !== src) : [...current, src],
      }
    })
    setCursor(undefined)
  }

  const handleRowClick = (err: AdminErrorLogRow) => {
    setSelectedError(err)
    setSheetOpen(true)
  }

  return (
    <div className="space-y-6">
      <PageHeader
        title="Error Log"
        description="Client and server errors captured across the platform."
      />

      {/* KPI row */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        {statsLoading ? (
          Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="h-24 rounded-xl bg-muted/40 animate-pulse" />
          ))
        ) : (
          <>
            <KpiCard
              title="Unresolved"
              value={stats?.unresolved ?? 0}
              icon={AlertCircle}
              iconColor={stats?.unresolved ? 'text-red-500' : 'text-muted-foreground'}
              iconBg={stats?.unresolved ? 'bg-red-50' : 'bg-muted/50'}
              valueColor={stats?.unresolved ? 'text-red-600' : 'text-foreground'}
            />
            <KpiCard
              title="Last 24h"
              value={stats?.count24h ?? 0}
              icon={Activity}
              iconColor="text-amber-500"
              iconBg="bg-amber-50"
            />
            <KpiCard
              title="Fatal (7d)"
              value={stats?.fatal7d ?? 0}
              icon={AlertTriangle}
              iconColor={stats?.fatal7d ? 'text-red-500' : 'text-muted-foreground'}
              iconBg={stats?.fatal7d ? 'bg-red-50' : 'bg-muted/50'}
              valueColor={stats?.fatal7d ? 'text-red-600' : 'text-foreground'}
            />
            <KpiCard
              title="Resolved"
              value={(stats?.count24h ?? 0) - (stats?.unresolved ?? 0) > 0
                ? (stats?.count24h ?? 0) - (stats?.unresolved ?? 0)
                : 0}
              icon={CheckCircle2}
              iconColor="text-green-500"
              iconBg="bg-green-50"
            />
          </>
        )}
      </div>

      {/* Filter bar */}
      <Card className="border-border/50 shadow-sm">
        <CardContent className="p-4 space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
              <Input
                placeholder="Search message…"
                value={search}
                onChange={(e) => { setSearch(e.target.value); setCursor(undefined) }}
                className="pl-8 h-8 text-sm"
              />
              {search && (
                <button
                  type="button"
                  onClick={() => { setSearch(''); setCursor(undefined) }}
                  className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                  aria-label="Clear search"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              )}
            </div>

            <div className="flex items-center gap-1">
              {(['fatal', 'error', 'warning', 'info'] as SeverityKey[]).map((sev) => (
                <Toggle
                  key={sev}
                  pressed={filters.severity?.includes(sev) ?? false}
                  onPressedChange={() => toggleSeverity(sev)}
                  size="sm"
                  className="h-8 text-xs capitalize"
                  aria-label={`Filter by ${sev}`}
                >
                  {sev}
                </Toggle>
              ))}
            </div>

            <div className="flex items-center gap-1">
              {(['server', 'client', 'edge', 'cron'] as SourceKey[]).map((src) => (
                <Toggle
                  key={src}
                  pressed={filters.source?.includes(src) ?? false}
                  onPressedChange={() => toggleSource(src)}
                  size="sm"
                  className="h-8 text-xs capitalize"
                  aria-label={`Filter by ${src}`}
                >
                  {src}
                </Toggle>
              ))}
            </div>

            <Toggle
              pressed={filters.resolved === true}
              onPressedChange={(v) => { setFilters((prev) => ({ ...prev, resolved: v ? true : false })); setCursor(undefined) }}
              size="sm"
              className="h-8 text-xs"
              aria-label="Show resolved"
            >
              Show Resolved
            </Toggle>
          </div>
        </CardContent>
      </Card>

      {/* Table */}
      <Card className="border-border/50 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-semibold">
            Errors
            {data?.items.length !== undefined && (
              <span className="ml-2 text-muted-foreground font-normal">({data.items.length} shown)</span>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {isLoading ? (
            <div className="p-4 space-y-2">
              {Array.from({ length: 5 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full" />
              ))}
            </div>
          ) : !data?.items.length ? (
            <div className="py-10 text-center">
              <CheckCircle2 className="mx-auto h-10 w-10 text-muted-foreground/30 mb-3" />
              <p className="text-sm font-medium text-foreground">No errors found</p>
              <p className="text-xs text-muted-foreground mt-1">Adjust filters or enjoy the quiet.</p>
            </div>
          ) : (
            <>
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/40 hover:bg-muted/40">
                    <TableHead className="w-[90px]">Severity</TableHead>
                    <TableHead>Message</TableHead>
                    <TableHead className="w-[80px]">Source</TableHead>
                    <TableHead className="w-[140px]">Route</TableHead>
                    <TableHead className="w-[100px]">Age</TableHead>
                    <TableHead className="w-[80px]">Status</TableHead>
                    <TableHead className="w-[40px]" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.items.map((err) => {
                    const sevConfig = SEVERITY_CONFIG[err.severity as SeverityKey]
                    const srcClass = SOURCE_CONFIG[err.source as SourceKey] ?? 'bg-muted/50 text-foreground/80 border-0'
                    return (
                      <TableRow
                        key={err.id}
                        className="hover:bg-muted/20 cursor-pointer"
                        onClick={() => handleRowClick(err)}
                      >
                        <TableCell>
                          <Badge className={`text-2xs px-1.5 py-0 capitalize ${sevConfig?.color ?? ''}`}>
                            {err.severity}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <p className="text-sm text-foreground truncate max-w-[280px]" title={err.message}>
                            {err.message}
                          </p>
                        </TableCell>
                        <TableCell>
                          <Badge className={`text-2xs px-1.5 py-0 capitalize ${srcClass}`}>
                            {err.source}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-xs text-muted-foreground font-mono truncate max-w-[140px]">
                          {err.route ?? '—'}
                        </TableCell>
                        <TableCell className="text-xs text-muted-foreground tabular-nums">
                          {formatDistanceToNow(new Date(err.occurred_at), { addSuffix: true })}
                        </TableCell>
                        <TableCell>
                          {err.resolved ? (
                            <Badge className="text-2xs px-1.5 py-0 bg-[--color-success-subtle] text-[--color-success-fg] border-0">
                              Resolved
                            </Badge>
                          ) : (
                            <Badge className="text-2xs px-1.5 py-0 bg-[--color-danger-subtle] text-[--color-danger-fg] border-0">
                              Open
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/50" />
                        </TableCell>
                      </TableRow>
                    )
                  })}
                </TableBody>
              </Table>
              {data.nextCursor && (
                <div className="p-3 border-t border-border/50 flex justify-center">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setCursor(data.nextCursor ?? undefined)}
                  >
                    Load more
                  </Button>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      <ErrorDetailSheet
        error={selectedError}
        open={sheetOpen}
        onClose={() => { setSheetOpen(false); setSelectedError(null) }}
        isSuperAdmin={isSuperAdmin}
      />
    </div>
  )
}

