/**
 * Impersonation cookie signing/verification using Web Crypto API.
 * Works in both Node.js (server actions, API routes) and Edge Runtime (middleware).
 */

export const IMPERSONATION_COOKIE = 'convertscan_impersonation'

export interface ImpersonationPayload {
  admin_id: string
  target_id: string
  session_id: string
  expires_ts: number
}

function getSecret(): string {
  const secret = process.env.IMPERSONATION_COOKIE_SECRET
  if (!secret) {
    throw new Error('CONFIG_ERROR: IMPERSONATION_COOKIE_SECRET is not set')
  }
  return secret
}

function buildPayloadString(p: ImpersonationPayload): string {
  return `${p.admin_id}.${p.target_id}.${p.session_id}.${p.expires_ts}`
}

async function getHmacKey(secret: string): Promise<CryptoKey> {
  const enc = new TextEncoder()
  return crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify'],
  )
}

function arrayBufferToBase64Url(buf: ArrayBuffer): string {
  const bytes = new Uint8Array(buf)
  let binary = ''
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]!)
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '')
}

function base64UrlToArrayBuffer(b64: string): ArrayBuffer {
  const padded = b64.replace(/-/g, '+').replace(/_/g, '/') + '=='.slice(0, (4 - b64.length % 4) % 4)
  const binary = atob(padded)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i)
  }
  return bytes.buffer
}

/**
 * Signs an impersonation cookie value.
 * Format: base64url(payload).hmac_base64url
 */
export async function signImpersonationCookie(p: ImpersonationPayload): Promise<string> {
  const secret = getSecret()
  const payload = buildPayloadString(p)
  const enc = new TextEncoder()
  const key = await getHmacKey(secret)
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(payload))
  const payloadB64 = arrayBufferToBase64Url(enc.encode(payload).buffer as ArrayBuffer)
  const hmac = arrayBufferToBase64Url(sig)
  return `${payloadB64}.${hmac}`
}

/**
 * Verifies a signed cookie value and returns the payload, or null if invalid/expired.
 */
export async function verifyImpersonationCookie(raw: string): Promise<ImpersonationPayload | null> {
  try {
    const secret = getSecret()
    const dotIdx = raw.lastIndexOf('.')
    if (dotIdx === -1) return null

    const payloadB64 = raw.slice(0, dotIdx)
    const hmacB64 = raw.slice(dotIdx + 1)

    const enc = new TextEncoder()
    const payloadBytes = base64UrlToArrayBuffer(payloadB64)
    const payload = new TextDecoder().decode(payloadBytes)

    const key = await getHmacKey(secret)
    const sigBytes = base64UrlToArrayBuffer(hmacB64)

    const valid = await crypto.subtle.verify('HMAC', key, sigBytes, enc.encode(payload))
    if (!valid) return null

    const parts = payload.split('.')
    if (parts.length !== 4) return null

    const admin_id = parts[0]
    const target_id = parts[1]
    const session_id = parts[2]
    const expires_ts_str = parts[3]

    if (!admin_id || !target_id || !session_id || !expires_ts_str) return null

    const expires_ts = parseInt(expires_ts_str, 10)
    if (isNaN(expires_ts)) return null

    if (expires_ts < Date.now()) return null

    return { admin_id, target_id, session_id, expires_ts }
  } catch {
    return null
  }
}

